#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json
ROOT=Path('/home/ubuntu/CHAOS'); LEDGER=ROOT/'research_ledger/RESEARCH_LEDGER_V1.jsonl'; OUT=ROOT/'experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1'
def h(rel): return hashlib.sha256((ROOT/rel).read_bytes()).hexdigest()
def make(i,t,status,contract,inputs,outputs,notes):
 r={'ledger_id':i,'record_type':t,'status':status,'contract_ref':contract,'created_at_utc':datetime.now(timezone.utc).isoformat(),'input_hashes':{x:h(x) for x in inputs if (ROOT/x).exists()},'output_refs':outputs,'notes':notes}; r['record_hash']=hashlib.sha256(json.dumps(r,sort_keys=True,ensure_ascii=False).encode()).hexdigest(); return r
rows=[make('IMF_PARTNER_DEPENDENCE_EXECUTION_V1','experiment_run','not_testable','experimental_contracts/IMF_IMTS_DOMINANT_PARTNER_DEPENDENCE_CONTRACT_V1.json',['experimental_contracts/IMF_IMTS_DOMINANT_PARTNER_DEPENDENCE_CONTRACT_V1.json','experiments/multi_domain_native_adapters_v1/imf_imts_v1/IMF_IMTS_OBSERVED_RECORDS_2000_2024.csv','catalog_first/readiness_gate/macro_plus_eia_energy/MACRO_PLUS_EIA_ENERGY_COMPLETE_139_NUMERIC_RAW_2000_2024_WIDE.csv'],['experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1/IMF_IMTS_PARTNER_DEPENDENCE_RUN_MANIFEST_V1.json','experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1/IMF_IMTS_PARTNER_DEPENDENCE_SUMMARY_V1.json'],'Actual run authorized by user; 15 reporters; selection window 2000-2004; 255 reporter-year rows; no causal or runtime promotion.'),make('IMF_PARTNER_DEPENDENCE_NULLS_V1','null_controls','not_testable','experimental_contracts/IMF_IMTS_DOMINANT_PARTNER_DEPENDENCE_CONTRACT_V1.json',['experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1/IMF_IMTS_PARTNER_DEPENDENCE_SUMMARY_V1.json'],['experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1/IMF_IMTS_PARTNER_IDENTITY_NULL_SUMMARY_V1.json','experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1/IMF_IMTS_OUTCOME_NULL_SUMMARY_V1.json'],'Identity null p=1.0 and SD=0 due degenerate confirmation structure; outcome null p=1.0.'),make('IMF_PARTNER_DEPENDENCE_RESULT_V1','transition_evidence','not_testable','experimental_contracts/IMF_IMTS_DOMINANT_PARTNER_DEPENDENCE_CONTRACT_V1.json',['experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1/IMF_IMTS_PARTNER_DEPENDENCE_SUMMARY_V1.json'],['experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1/IMF_IMTS_PARTNER_DEPENDENCE_TRANSITION_EVIDENCE_V1.jsonl','experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1/IMF_IMTS_PARTNER_DEPENDENCE_TEST_REPORT_AR.md'],'Confirmation exposure count=1 below five; all confirmation risk differences negative; concentration gate fails.'),make('IMF_PARTNER_DEPENDENCE_GOVERNANCE_V1','supervisor_gate','pass','experimental_contracts/IMF_IMTS_DOMINANT_PARTNER_DEPENDENCE_CONTRACT_V1.json',['experiments/multi_domain_native_edges_v1/imf_partner_dependence_v1/IMF_IMTS_PARTNER_DEPENDENCE_TRANSITION_EVIDENCE_V1.jsonl'],['campaigns/CAMPAIGN_SHARED_GATE_V1/FINAL_SUPERVISOR_ELIGIBILITY_GATE_V1.json','experiments/macro_plus_eia_energy/evidence_graph_v1/EVIDENCE_GRAPH_SUMMARY.json'],'New transition remained quarantined; no positive Composer/runtime admission.')]
old=LEDGER.read_text(encoding='utf8').splitlines(); ids={json.loads(x)['ledger_id'] for x in old if x.strip()}; new=[x for x in rows if x['ledger_id'] not in ids]
with LEDGER.open('a',encoding='utf8') as f:
 for r in new:f.write(json.dumps(r,ensure_ascii=False,sort_keys=True)+'\n')
print(json.dumps({'appended':[x['ledger_id'] for x in new],'total_records':len(old)+len(new)},ensure_ascii=False,indent=2))
